// Правец-8А для СССР: клавиатура на токопроводящей резине (плата Е37.102.026,
// микро-ЭВМ СМ650), латиница QWERTY, кириллица по ГОСТ (ЙЦУКЕН).
//
// Клавиша хоста[/модификаторы]: код. S - Shift, R - кириллица (C/L Lock),
// 8 - 8-битная кодовая таблица (MODE1). Коды 7-битной таблицы - со стробом в
// разряде 7, как их читает $C000 (книга П. Петрова, табл. 2.1, П8.1-П8.4).
// В 8-битной таблице буква без Shift и без Caps Lock - строчная: код - $80
// (латиница $40-$5F, кириллица $60-$7F); это правило клавиатуры, его здесь
// не пишут. Запись с 8 отдается как есть. Код 0 - клавиша ничего не дает.
//
// C/L Lock - F10, Caps Lock - Caps Lock, F1/F2 - F1/F2, RESET - F12 (только с Ctrl).

// Буквы, латиница
A: $C1
B: $C2
C: $C3
D: $C4
E: $C5
F: $C6
G: $C7
H: $C8
I: $C9
J: $CA
K: $CB
L: $CC
M: $CD
N: $CE
O: $CF
P: $D0
Q: $D1
R: $D2
S: $D3
T: $D4
U: $D5
V: $D6
W: $D7
X: $D8
Y: $D9
Z: $DA

// Буквы, кириллица ГОСТ: КОИ-7, Ю=$E0 ... Ч=$FE, Ъ=$F9
Q/R: $EA            // Й
W/R: $E3            // Ц
E/R: $F5            // У
R/R: $EB            // К
T/R: $E5            // Е
Y/R: $EE            // Н
U/R: $E7            // Г
I/R: $FB            // Ш
O/R: $FD            // Щ
P/R: $FA            // З
[/R: $E8            // Х
{/SR: $E8
]/R: $F9            // Ъ
}/SR: $F9
A/R: $E6            // Ф
S/R: 0              // Ы: в 7-битной таблице его нет
S/R8: $7F           // ы - знакогенератор для СССР, позиция $7F
S/SR8: $5F          // Ы - позиция $5F
D/R: $F7            // В
F/R: $E1            // А
G/R: $F0            // П
H/R: $F2            // Р
J/R: $EF            // О
K/R: $EC            // Л
L/R: $E4            // Д
semicolon/R: $F6    // Ж
colon/SR: $F6
'/R: $FC            // Э
"/SR: $FC
Z/R: $F1            // Я
X/R: $FE            // Ч
C/R: $F3            // С
V/R: $ED            // М
B/R: $E9            // И
N/R: $F4            // Т
M/R: $F8            // Ь
,/R: $E2            // Б
</SR: $E2
./R: $E0            // Ю
>/SR: $E0
slash/R: $AE        // .
?/SR: $AC           // ,

// Цифры и знаки
0: $B0
1: $B1
2: $B2
3: $B3
4: $B4
5: $B5
6: $B6
7: $B7
8: $B8
9: $B9
!/S: $A1
@/S: $C0
#/S: $A3
$/S: $A4
%/S: $A5
^/S: $DE
&/S: $A6
*/S: $AA
(/S: $A8
)/S: $A9
-: $AD
_/S: $DF
=: $BD
+/S: $AB
semicolon: $BB
colon/S: $BA
': $A7
"/S: $A2
,: $AC
</S: $BC
.: $AE
>/S: $BE
slash: $AF
?/S: $BF

// Скобки: в 8-битной таблице без Shift - строчные { | } ~ `
[: $DB
{/S: $DB
{/S8: $5B
]: $DD
}/S: $DD
}/S8: $5D
\: $DC
bar/S: $DC
bar/S8: $5C
tilde/S: $DE
tilde/S8: $5E
~: $C0
~/8: $40

// Управляющие
space: $A0
ret: $8D
enter: $8D
esc: $9B
tab: $89
back: $88
left: $88
right: $95
up: $8B
down: $8A
del: $FF
